table.ko-pron {
	border: 1px solid var(--wikt-palette-lightgrey, #CCCCCC);
    min-width: 13em;
    display: table;
}

table.ko-pron th {
	padding: .4em;
	color: var(--wikt-palette-black, #202122);
	text-align: left;
	background-color: var(--wikt-palette-lavender, #f8f8ff);
}

table.ko-pron td {
	padding: .4em;
}

.ko-pron__ph {
	font-size: 110%;
}

.ko-pron__ph b {
	font-size: inherit;
	color: var(--wikt-palette-deepred, #bf0218);
}

.ko-pron__note-vowel-length {
	font-size: smaller;
	font-style: italic;
}

.ko-acc-H {
	font-weight: bold;
	color: red;
}

.ko-acc-F {
	font-weight: bold;
	color: purple;
}

.ko-acc-R {
	font-weight: bold;
	color: blue;
}
